from binance import Client, BinanceSocketManager

manager = BinanceSocketManager(client_secret=os.getenv('BINANCE_CLIENT_SECRET'))
client = Client(client_secret=os.getenv('BINANCE_CLIENT_SECRET'), socket_manager=manager)

stream_channel_responses = manager.subscribe_channels(['/binance/stocks/level2'])

def process_message(msg):
    print(msg)

for resp in stream_channel_responses:
    for message in resp.messages:
        process_message(message.data['p'])

manager.close()

